PLANNED = 'planned'


def _renumber(groups):
    # States take the next minor number under their resting screen, in order.
    out, seen = [], {}
    for gid, gtitle, entries in groups:
        rows = []
        for n, *rest in entries:
            major = n.split(".")[0]
            k = seen.get(major, -1) + 1
            seen[major] = k
            rows.append((major if k == 0 else f"{major}.{k}", *rest))
        out.append((gid, gtitle, rows))
    return out


GROUPS = _renumber(GROUPS)


def flat():
    for gid, gtitle, entries in GROUPS:
        for entry in entries:
            yield (gid, gtitle) + entry
